'One newly authored static whole-bryophyte teaching comparison arrangement, one scene and zero new independent models. Three complete accepted originals retain their own illustrative dimensions: the entire forked notched liverwort and all gemma cups lie on the front-left wing, the whole lobed hornwort and all five complete capsule assemblies occupy the front-right wing, and the entire leafy moss with every leaf, rhizoid, seta, capsule and tooth stands on a low rear-left step. A new broad continuous U-shaped scene-only bench has two grounded front wings, an open central front notch, and one low rear step, not the old elevated branching three-pad rack or a replacement pair on its original flat slab. Every original GLB binary payload, normal/index stream, complete material dictionary and internal node hierarchy is preserved; only whole-instance translations are added, with no resizing, trimming, recolouring or repeated model counts. The models depict different representative external forms and different artistic enlargement factors, not measured relative biological sizes, a common colony, a complete life cycle, a phylogenetic ladder or universal morphology of their groups. The bench is an artificial classroom juxtaposition, not a habitat, soil system or natural growth surface. No new independent botanical asset is claimed. No labels, textures, working instrument, stability/load certification, cultivation, physiology, rig, animation or interaction.'
import base64,copy,hashlib,json,math,struct,lzma
from pathlib import Path
ASSET='education-whole-three-bryophytes-and-u-shaped-comparison-bench-scene-01'
TITLE='Whole Three Bryophytes and U-Shaped Comparison Bench Scene'
TOL=2e-7
OFFSETS={'liverwort':(-.100,-.055,.012),'moss':(-.060,.075,.028),'hornwort':(.095,-.015,.012)}
ROTATIONS={k:(1,0) for k in OFFSETS}
def f32(x):return struct.unpack('<f',struct.pack('<f',x))[0]
def wrapper_matrix(key):
 # Exact determinant +1 signed permutation in glTF Y-up, column-major.
 # No quaternion, data baking, normal setter or simultaneous node TRS.
 c,s=ROTATIONS[key];x,y,z=OFFSETS[key]
 return [c,0,-s,0,0,1,0,0,s,0,c,0,f32(x),f32(z),f32(-y),1]
def unpack_glb(raw):
 magic,version,size=struct.unpack_from('<4sII',raw);assert magic==b'glTF' and version==2 and size==len(raw)
 n,kind=struct.unpack_from('<II',raw,12);assert kind==0x4e4f534a
 doc=json.loads(raw[20:20+n]);p=20+n;length,kind=struct.unpack_from('<II',raw,p);assert kind==0x004e4942
 blob=raw[p+8:p+8+length];assert len(blob)==length and len(doc['buffers'])==1
 assert doc['buffers'][0]['byteLength']<=len(blob)
 return doc,blob

def pack_glb(doc,blob):
 j=json.dumps(doc,separators=(',',':'),allow_nan=False).encode();j+=b' '*((-len(j))%4)
 b=bytes(blob)+b'\0'*((-len(blob))%4)
 return struct.pack('<4sII',b'glTF',2,12+8+len(j)+8+len(b))+struct.pack('<II',len(j),0x4e4f534a)+j+struct.pack('<II',len(b),0x004e4942)+b

def compose(inputs):
 d=dict(asset={'version':'2.0','generator':'Source-preserving static scene composition'},scene=0,scenes=[{'name':TITLE,'nodes':[0]}],nodes=[{'name':'AssetRoot__'+ASSET,'children':[]}],meshes=[],materials=[],accessors=[],bufferViews=[],buffers=[])
 blob=bytearray();proof={}
 for key in ['liverwort','moss','hornwort']:
  raw=inputs[key];src,b=unpack_glb(raw)
  assert not any(src.get(x) for x in ['textures','images','skins','animations','cameras','extensionsUsed','extensionsRequired'])
  assert not any(any(k in n for k in ['skin','camera']) for n in src['nodes'])
  start=len(blob);blob.extend(b);blob.extend(b'\0'*((-len(blob))%4))
  vi,ai,mi,ni,pi=(len(d[k]) for k in ['bufferViews','accessors','meshes','nodes','materials'])
  for old in src['bufferViews']:
   v=copy.deepcopy(old);assert v['buffer']==0;v['byteOffset']=v.get('byteOffset',0)+start;d['bufferViews'].append(v)
  for old in src['accessors']:
   a=copy.deepcopy(old);assert 'sparse' not in a;a['bufferView']+=vi;d['accessors'].append(a)
  d['materials'].extend(copy.deepcopy(src['materials']));assert d['materials'][pi:pi+len(src['materials'])]==src['materials']
  for old in src['meshes']:
   m=copy.deepcopy(old)
   for p in m['primitives']:
    assert p.get('mode',4)==4 and not p.get('targets');p['indices']+=ai;p['material']+=pi
    p['attributes']={k:v+ai for k,v in p['attributes'].items()}
   d['meshes'].append(m)
  for old in src['nodes']:
   n=copy.deepcopy(old);n.setdefault('extras',{})['whole_original_node_name']=n.get('name','');n['name']=key+'__'+n.get('name','node')
   if 'mesh'in n:n['mesh']+=mi
   if 'children'in n:n['children']=[x+ni for x in n['children']]
   d['nodes'].append(n)
  wrapper=len(d['nodes']);d['nodes'].append({'name':'INSTANCE__'+key,'matrix':wrapper_matrix(key),'children':[x+ni for x in src['scenes'][src.get('scene',0)]['nodes']]});d['nodes'][0]['children'].append(wrapper)
  proof[key]={'source_glb_sha256':hashlib.sha256(raw).hexdigest(),'original_meshes':len(src['meshes']),'original_payload_bytes_unchanged':True,'original_internal_TRS_and_matrix_unchanged':True,'unit_scale':True,'rotation_degrees':0,'translation_zup_m':[f32(x)for x in OFFSETS[key]],'buffer_range':[start,start+len(b)]}
  assert bytes(blob[start:start+len(b)])==b
 floor,materials=make_floor();material_base=len(d['materials']);d['materials'].extend(materials)
 def array(values,component,kind):
  flat=[v for row in values for v in row] if kind=='VEC3' else values;fmt='f' if component==5126 else 'I'
  raw=struct.pack('<'+fmt*len(flat),*flat);offset=len(blob);blob.extend(raw);blob.extend(b'\0'*((-len(blob))%4));view=len(d['bufferViews']);d['bufferViews'].append({'buffer':0,'byteOffset':offset,'byteLength':len(raw)})
  a={'bufferView':view,'componentType':component,'count':len(values),'type':kind}
  if kind=='VEC3':a.update(min=[min(p[k]for p in values)for k in range(3)],max=[max(p[k]for p in values)for k in range(3)])
  index=len(d['accessors']);d['accessors'].append(a);return index
 primitives=[]
 for material in range(len(materials)):
  positions=[];normals=[]
  for tri,mat in floor:
   if mat!=material:continue
   a,b,c=tri;u=[b[k]-a[k]for k in range(3)];v=[c[k]-a[k]for k in range(3)];n=(u[1]*v[2]-u[2]*v[1],u[2]*v[0]-u[0]*v[2],u[0]*v[1]-u[1]*v[0]);length=math.sqrt(sum(x*x for x in n));assert length>0;n=[x/length for x in n]
   positions.extend((x,z,-y)for x,y,z in tri);normals.extend([(n[0],n[2],-n[1])]*3)
  primitives.append({'attributes':{'POSITION':array(positions,5126,'VEC3'),'NORMAL':array(normals,5126,'VEC3')},'indices':array(list(range(len(positions))),5125,'SCALAR'),'material':material_base+material,'mode':4})
 mesh=len(d['meshes']);d['meshes'].append({'name':'SceneOnlyContinuousUBenchAndRearStep','primitives':primitives});node=len(d['nodes']);d['nodes'].append({'name':'SCENE_ONLY__ContinuousUBenchAndRearStep','mesh':mesh,'extras':{'new_independent_model':False}});d['nodes'][0]['children'].append(node);d['buffers']=[{'byteLength':len(blob)}]
 assert len(d['meshes'])==80 and len(d['materials'])==19
 proof['floor_triangles']=len(floor);proof['triangles']=27088+len(floor);proof['single_scene_count']=1;proof['new_independent_model_count']=0
 return d,bytes(blob),proof

def make_floor():
 # Entire new low U-bench and rear step. No old branching rack component.
 ts=[]
 def cross2(a,b,c):return(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0])
 def earclip(poly):
  ids=list(range(len(poly)));out=[]
  assert sum(a[0]*b[1]-b[0]*a[1]for a,b in zip(poly,poly[1:]+poly[:1]))>0
  while len(ids)>3:
   for j,b in enumerate(ids):
    a,c=ids[j-1],ids[(j+1)%len(ids)]
    if cross2(poly[a],poly[b],poly[c])<=1e-12:continue
    if any(all(cross2(poly[u],poly[v],poly[k])>=-1e-12 for u,v in[(a,b),(b,c),(c,a)])for k in ids if k not in[a,b,c]):continue
    out.append((a,b,c));ids.pop(j);break
   else:raise AssertionError('Non-simple scene-only support plan')
  out.append(tuple(ids));return out
 def prism(poly,z0,z1,mat):
  for a,b,c in earclip(poly):
   ts.append((tuple((poly[i][0],poly[i][1],z1)for i in[a,b,c]),mat));ts.append((tuple((poly[i][0],poly[i][1],z0)for i in[c,b,a]),mat))
  for a,b in zip(poly,poly[1:]+poly[:1]):
   aa=(*a,z0);bb=(*b,z0);cc=(*b,z1);dd=(*a,z1);ts.extend([((aa,bb,cc),mat),((aa,cc,dd),mat)])
 base=[(-.175,-.12),(-.028,-.12),(-.028,.008),(.028,.008),(.028,-.12),(.175,-.12),(.19,-.09),(.19,.08),(.145,.12),(-.145,.12),(-.19,.08),(-.19,-.09)]
 step=[(-.14,.035),(.015,.035),(.015,.095),(-.01,.11),(-.12,.11),(-.15,.08)]
 prism(base,0,.012,0);prism(step,.010,.028,1)
 assert len(ts)==64
 return ts,[{'name':'SceneOnlyUBench_QuietClay','doubleSided':False,'pbrMetallicRoughness':{'baseColorFactor':[.27,.24,.18,1],'metallicFactor':0.,'roughnessFactor':.90}},{'name':'SceneOnlyLowRearStep_WarmStone','doubleSided':False,'pbrMetallicRoughness':{'baseColorFactor':[.36,.32,.24,1],'metallicFactor':0.,'roughnessFactor':.87}}]

